window.kbPageData["views/entry/k-327f63b6606c579e"] = {"key":"entry/k-327f63b6606c579e","state":{"route":"entry/k-327f63b6606c579e"},"node":{"id":"k-327f63b6606c579e","mode":"k","title":"“一企包一县”的竞争与收益风险","type":"观点与论证","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":["整县光伏独家开发的竞争与农户收益风险"],"qs":["国考 2023 地市级 申论#3"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"“一企包一县”是指地方政府将全县屋顶光伏资源打包交给一家企业开发。S市调研组发现，采用这一模式的地区农户每块光伏板的年收益普遍约为40元，其他地区约为50元。","review":{"definition":"“一企包一县”是指地方政府将全县屋顶光伏资源打包交给一家企业开发。S市调研组发现，采用这一模式的地区农户每块光伏板的年收益普遍约为40元，其他地区约为50元。","explanation":"独家开发压缩了其他企业的竞争机会，也限制了农户选择租金更高的企业。专家谭先生认为，部分承接项目的大企业主攻集中式光伏、对分布式市场不熟悉，这可能是收益差异的原因之一。题中可用这一地区对比说明农户收益风险，并支持向合格企业开放市场的建议。","references":[],"evidence":"而在S市已实行“一企包一县”的区域，收益则普遍降低至40元左右。","disposition":"题内说明","basis":"据原题和解析编释。"}},"questions":{"国考 2023 地市级 申论#3":{"paper":"国考 2023 地市级 申论","n":3,"mod":"申论","src":["ac29447768aa30db2247.pdf",4],"asrc":["88c33effee950c9e9e6a.pdf",2],"card":"1d8d12a97d067412758af23f","links":[{"id":"k-327f63b6606c579e","role":"直接考查","why":"材料中的区域对比支持识别独家开发的农户收益风险，并为开放合格企业参与竞争提供理由。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-327f63b6606c579e":[["国考 2023 地市级 申论#3"]]}};
